    (1, {"時間": "15:00", "地點": "M17", "格式": "一小段文字"}),
    (3, {"時間": "16:00"}),
    (4, {"格式": "兩個條列"}),
]


def plan_as_of(day):
    plan = {}
    for message_day, change in updates:
        if message_day <= day:
            plan.update(change)
    return plan


